import { readFileSync, readdirSync } from 'node:fs';
import { resolve } from 'node:path';

type PackageExports = Record<string, string | Record<string, unknown>>;

export type MarklessPackageAlias = {
	find: RegExp;
	replacement: string;
	customResolver?: (specifier: string) => never;
};

const escapeForRegExp = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function sourceTarget(target: string | Record<string, unknown>): string | undefined {
	if (typeof target === 'string') return target;
	for (const condition of ['import', 'default', 'require', 'types']) {
		const candidate = target[condition];
		if (typeof candidate === 'string') return candidate;
		if (candidate && typeof candidate === 'object') {
			const nested = sourceTarget(candidate as Record<string, unknown>);
			if (nested) return nested;
		}
	}
	return undefined;
}

export function createMarklessPackageAliases(marklessRoot: string): MarklessPackageAlias[] {
	const packagesRoot = resolve(marklessRoot, 'packages');
	const aliases = readdirSync(packagesRoot, { withFileTypes: true })
		.filter((entry) => entry.isDirectory())
		.flatMap((entry) => {
			const packageRoot = resolve(packagesRoot, entry.name);
			const manifest = JSON.parse(readFileSync(resolve(packageRoot, 'package.json'), 'utf8')) as {
				name?: string;
				exports?: PackageExports;
			};
			if (!manifest.name?.startsWith('@markless/') || !manifest.exports) return [];

			return Object.entries(manifest.exports).flatMap(([subpath, target]) => {
				const source = sourceTarget(target);
				if (!source) return [];
				const identifier = subpath === '.' ? manifest.name! : `${manifest.name}${subpath.slice(1)}`;
				const star = identifier.indexOf('*');
				if (star === -1) {
					return [{ find: new RegExp(`^${escapeForRegExp(identifier)}$`), replacement: resolve(packageRoot, source) }];
				}
				const find = new RegExp(
					`^${escapeForRegExp(identifier.slice(0, star))}([^/]+)${escapeForRegExp(identifier.slice(star + 1))}$`,
				);
				return [{ find, replacement: resolve(packageRoot, source.replace('*', '$1')) }];
			});
		});

	return [
		...aliases,
		{
			find: /^@markless(?:\/.*)?$/,
			replacement: '',
			customResolver(specifier: string): never {
				throw new Error(`Unknown @markless package export: ${specifier}`);
			},
		},
	];
}
