import { resolve } from 'node:path';
import { describe, expect, test } from 'vitest';
import { createMarklessPackageAliases } from '../../demos/js-framework-benchmark/frameworks/keyed/markless/package-aliases';

const workspaceRoot = resolve(import.meta.dirname, '../..');

describe('JS Framework Benchmark package aliases', () => {
	test('derives anchored package and subpath aliases from package exports', () => {
		const aliases = createMarklessPackageAliases(workspaceRoot);
		const core = aliases.find((alias) => alias.find.test('@markless/core'));
		const coreResume = aliases.find((alias) => alias.find.test('@markless/core/web/resume'));

		expect(core?.find.test('@markless/core/web/resume')).toBe(false);
		expect(core?.replacement).toBe(resolve(workspaceRoot, 'packages/core/src/index.ts'));
		expect(coreResume?.replacement).toBe(
			resolve(workspaceRoot, 'packages/core/src/web/resume.ts'),
		);
	});

	test('expands exported wildcard subpaths without accepting neighboring identifiers', () => {
		const aliases = createMarklessPackageAliases(workspaceRoot);
		const webFunction = aliases.find((alias) => alias.find.test('@markless/web/fns/class-list'));

		expect('@markless/web/fns/class-list'.replace(webFunction!.find, webFunction!.replacement)).toBe(
			resolve(workspaceRoot, 'packages/web/src/fns/class-list.ts'),
		);
		expect(webFunction?.find.test('@markless/web/fns/class-list/extra')).toBe(false);
	});

	test('fails closed when no package export owns an @markless identifier', async () => {
		const aliases = createMarklessPackageAliases(workspaceRoot);
		const refusal = aliases.find((alias) => alias.find.test('@markless/core/not-exported'));
		const unresolved = '@markless/core/not-exported'.replace(
			refusal!.find,
			refusal!.replacement,
		);

		expect(() => refusal?.customResolver?.(unresolved)).toThrow(
			'Unknown @markless package export: @markless/core/not-exported',
		);
	});
});
import { expect, test } from 'vitest';
import { nodeTestProjects } from '../vite.config';

test('TypeScript plugin test files share one serial project because their CJS build cleans dist', () => {
	const generalNode = nodeTestProjects.find((project) => project.test.name === 'node');
	const typescriptPlugin = nodeTestProjects.find(
		(project) => project.test.name === 'typescript-plugin',
	);

	expect(generalNode?.test.exclude).toContain('packages/typescript-plugin/test/**/*.test.ts');
	expect(typescriptPlugin?.test).toMatchObject({
		fileParallelism: false,
		include: ['packages/typescript-plugin/test/**/*.test.ts'],
		exclude: ['packages/typescript-plugin/test/completion-matrix.test.ts'],
	});
});
